/* Three distinct, rounded cartoon rigs inspired by the requested references. */
window.buildMascots=function({round,capsule,group,material,shirtMat,pantsMat,shoesMat,capMat,runner}){
  const yellow=new THREE.MeshStandardMaterial({color:0xffd246,roughness:.42});
  const orange=new THREE.MeshStandardMaterial({color:0x5dace1,roughness:.65});
  const pink=new THREE.MeshStandardMaterial({color:0xf2b3a1,roughness:.5});
  const models={};
  function smile(parent,x,y,z,size,color=0x6d4439){const m=new THREE.Mesh(new THREE.TorusGeometry(size,.012,8,24,Math.PI),material(color));m.rotation.z=Math.PI;m.position.set(x,y,z);parent.add(m);return m;}
  function eyes(parent,y,z,x,size,iris){for(const side of [-1,1]){round(parent,side*x,y,z,size,size*1.22,.048,0xfffcf0);round(parent,side*x,y-.015,z-.045,size*.64,size*.84,.035,iris);round(parent,side*x,y-.005,z-.075,size*.36,size*.53,.022,0x252c31);round(parent,side*x-size*.18,y+size*.35,z-.099,size*.16,size*.21,.009,0xffffff);}}
  function accessories(parent,headY,headW,depth){
    const cap=group();round(cap,0,headY+.43,.025,headW*1.06,.23,depth,capMat);round(cap,0,headY+.32,-depth-.09,headW*.82,.038,.22,capMat);parent.add(cap);
    const star=group();const sh=new THREE.Shape();for(let i=0;i<10;i++){const a=Math.PI/2+i*Math.PI/5,r=i%2===0?.19:.085;if(i===0)sh.moveTo(Math.cos(a)*r,Math.sin(a)*r);else sh.lineTo(Math.cos(a)*r,Math.sin(a)*r);}sh.closePath();const emblem=new THREE.Mesh(new THREE.ExtrudeGeometry(sh,{depth:.02,bevelEnabled:true,bevelSize:.01,bevelThickness:.009,bevelSegments:2}),material(0xffd671));emblem.position.set(.23,1.05,-.47);emblem.rotation.y=Math.PI;star.add(emblem);const back=emblem.clone();back.position.set(.18,1.18,.43);back.rotation.y=0;star.add(back);parent.add(star);
    const cat=group();for(const side of [-1,1]){const ear=new THREE.Mesh(new THREE.ConeGeometry(.17,.27,3),capMat);ear.position.set(side*(headW*.72),headY+.62,0);cat.add(ear);const inner=new THREE.Mesh(new THREE.ConeGeometry(.09,.18,3),material(0xffb5b5));inner.position.set(side*(headW*.72),headY+.62,-.1);cat.add(inner);}parent.add(cat);
    const phones=group();const band=new THREE.Mesh(new THREE.TorusGeometry(headW+.075,.045,8,28,Math.PI),material(0x51476c));band.position.set(0,headY,.06);phones.add(band);for(const side of [-1,1]){round(phones,side*(headW+.05),headY,.035,.085,.16,.155,0xb3a0ed);round(phones,side*(headW+.1),headY,.035,.033,.1,.1,0x89edd9);}parent.add(phones);
    const crown=group();const base=new THREE.Mesh(new THREE.CylinderGeometry(headW*.62,headW*.66,.1,24,1,true),material(0xffcf63));base.position.y=headY+.53;crown.add(base);for(let i=0;i<5;i++){const a=i*Math.PI*2/5;const tip=new THREE.Mesh(new THREE.ConeGeometry(.08,.2,5),material(0xffd567));tip.position.set(Math.sin(a)*headW*.6,headY+.64,Math.cos(a)*headW*.6);crown.add(tip);round(crown,tip.position.x,headY+.76,tip.position.z,.035,.035,.035,0xffeab0);}parent.add(crown);return{cap,star,cat,phones,crown};
  }
  function limbsFor(parent,skin,shoulder,hip,armY,legY,short=false){const limbs=[];for(const side of [-1,1]){const arm=group();arm.position.set(side*shoulder,armY,0);capsule(arm,side*.025,-.15,0,short?.14:.115,short?.13:.24,shirtMat);round(arm,side*.025,short?-.31:-.43,-.01,short?.14:.13,short?.15:.15,.135,skin);parent.add(arm);const leg=group();leg.position.set(side*hip,legY,0);capsule(leg,0,-.15,0,short?.18:.145,short?.1:.17,pantsMat);round(leg,0,-.32,-.075,short?.22:.17,.14,.27,shoesMat);round(leg,0,-.4,-.075,short?.225:.175,.045,.275,0xfff6df);parent.add(leg);limbs.push({arm,leg,side});}return limbs;}
  // A broad, pear-shaped yellow dragon with a large snout and a thick tail.
  {const b=group();runner.add(b);round(b,0,.88,.035,.6,.72,.48,yellow);round(b,0,1.1,0,.57,.32,.46,shirtMat);round(b,0,.74,-.434,.44,.47,.065,0xffe9a0);round(b,0,1.76,-.02,.665,.55,.485,yellow);round(b,0,1.52,-.395,.49,.24,.237,yellow);eyes(b,1.86,-.45,.25,.162,0x79b640);for(const side of [-1,1]){round(b,side*.2,1.59,-.598,.036,.025,.009,0xbc9037);round(b,side*.41,1.63,-.463,.086,.035,.015,0xffc66c);}smile(b,0,1.395,-.589,.145,0x9d7030);for(const side of [-1,1]){const horn=new THREE.Mesh(new THREE.ConeGeometry(.09,.2,12),material(0xf2b332));horn.position.set(side*.4,2.21,.055);horn.rotation.z=side*.3;b.add(horn);}const tail=group();tail.position.set(0,.58,.42);for(let i=0;i<7;i++){const t=i/6;round(tail,t*.38,-t*.21,t*.85,.23*(1-t*.65),.22*(1-t*.65),.23,yellow);}b.add(tail);for(let i=0;i<4;i++){const p=new THREE.Mesh(new THREE.ConeGeometry(.11,.19,8),material(0xee9b32));p.position.set(0,1.45-i*.21,.47+i*.085);p.rotation.x=.6;b.add(p);}models.alo={body:b,limbs:limbsFor(b,yellow,.65,.31,1.23,.46,true),accessories:accessories(b,1.82,.6,.46),tail,kind:'dragon'};}
  // A wide blue cat with triangular ears, a white muzzle and a curved tail.
  {const b=group();runner.add(b);round(b,0,.84,.02,.66,.62,.5,orange);round(b,0,1.02,0,.65,.32,.5,shirtMat);round(b,0,.7,-.457,.47,.41,.065,0xf5f8fc);round(b,0,1.7,-.015,.73,.59,.49,orange);for(const side of [-1,1]){const ear=new THREE.Mesh(new THREE.ConeGeometry(.225,.46,3),orange);ear.position.set(side*.46,2.25,.02);ear.rotation.z=side*-.16;b.add(ear);const inner=new THREE.Mesh(new THREE.ConeGeometry(.13,.29,3),material(0xf2b0bb));inner.position.set(side*.46,2.26,-.13);b.add(inner);round(b,side*.175,1.54,-.485,.24,.155,.075,0xfffcf2);round(b,side*.215,1.79,-.46,.085,.11,.04,0x2a3b4b);round(b,side*.238,1.83,-.497,.023,.027,.009,0xffffff);for(let n=0;n<3;n++){const w=capsule(b,side*.48,1.535+(n-1)*.065,-.484,.008,.31,0x567186);w.rotation.z=Math.PI/2+side*(n-1)*.15;}}round(b,0,1.56,-.582,.061,.043,.029,0xe19aaa);smile(b,-.067,1.465,-.556,.067);smile(b,.067,1.465,-.556,.067);for(let x of [-.12,0,.12])round(b,x,2.17,-.2,.029,.125,.038,0x3984b7);const tail=group();tail.position.set(0,.54,.45);for(let n=0;n<9;n++){const a=n/8*1.45;round(tail,.16+Math.sin(a)*.57,n*.085,.1+Math.cos(a)*.24,.12,.13,.12,n%3===0?0x3984b7:orange);}b.add(tail);models.mia={body:b,limbs:limbsFor(b,0xf5f8fc,.7,.32,1.12,.44,true),accessories:accessories(b,1.75,.67,.46),tail,kind:'cat'};}
  // A pig hero: round snout, red hood and outfit, gold gloves and boots, cape and curled tail.
  {const b=group();runner.add(b);round(b,0,1,0,.46,.52,.32,shirtMat);round(b,0,.56,0,.34,.18,.28,pantsMat);round(b,0,1.83,0,.575,.57,.43,pink);for(const side of [-1,1]){round(b,side*.555,1.95,0,.105,.135,.06,pink);round(b,side*.58,1.955,-.047,.052,.075,.025,0xdd8e8e);}eyes(b,1.91,-.397,.214,.136,0x97582c);round(b,0,1.665,-.456,.226,.155,.116,pink);for(const side of [-1,1])round(b,side*.084,1.675,-.564,.028,.043,.009,0xcc7f83);smile(b,0,1.485,-.368,.16);for(const side of [-1,1]){const brow=capsule(b,side*.22,2.1,-.37,.03,.14,0x704034);brow.rotation.z=Math.PI/2+side*.1;round(b,side*.35,1.65,-.34,.058,.024,.015,0xea9997);}const accessory=accessories(b,1.9,.55,.43);round(accessory.cap,0,2.24,-.399,.127,.11,.023,0xffcb50);round(accessory.cap,0,2.24,-.428,.048,.068,.013,0xed6a51);const belt=new THREE.Mesh(new THREE.TorusGeometry(.36,.05,8,28),material(0xf7bf45));belt.rotation.x=Math.PI/2;belt.position.y=.75;b.add(belt);round(b,0,1.02,-.32,.15,.15,.03,0xffcf51);round(b,0,1.02,-.35,.072,.05,.016,0xed8750);for(const side of [-1,1])round(b,side*.029,1.02,-.368,.013,.016,.008,0xffd56b);const cape=new THREE.Mesh(new THREE.PlaneGeometry(.8,1.0,4,5),new THREE.MeshStandardMaterial({color:0xd13f4e,side:THREE.DoubleSide,roughness:.85}));cape.position.set(0,1.03,.4);cape.rotation.x=-.14;b.add(cape);const tail=new THREE.Mesh(new THREE.TorusGeometry(.08,.025,8,20,Math.PI*1.75),pink);tail.position.set(0,.55,.35);b.add(tail);models.bei={body:b,limbs:limbsFor(b,0xffcf51,.5,.2,1.34,.55,false),accessories:accessory,tail:cape,kind:'pig'};}
  for(const m of Object.values(models)){m.body.visible=false;for(const a of Object.values(m.accessories))a.visible=false;}
  return models;
};
